/**
 * Dynamic tools 的共享协议定义。Studio 工具由 View 实现；工作区和图片分类工具由 Runtime 实现。
 * Desktop 在 thread/start 时只提交 View 工具，Runtime 网关再合并自己执行的工具。
 * 需要用户确认的步骤（尺寸、耗材、超床决策、下载/发送）不做成工具参数，留在 Studio 面板。
 */
import { z } from 'zod';
import { SkillDraftPath, SkillCaptureSteps } from './skill-community';

export const SkillDraftSubmitArgs = z.object({ path: SkillDraftPath, summary: z.string().max(4000).optional(), exampleTask: z.string().max(4000).optional(),
  mergedInstalledRevisionId: z.string().min(1).max(512).optional().describe('Only after comparing and merging the current installed content into the workspace draft, supply that exact installed revision ID. Never use this to bypass an unresolved merge.') }).strict();
export type SkillDraftSubmitArgs = z.infer<typeof SkillDraftSubmitArgs>;
export const SkillCaptureSuggestArgs = z.object({ title: z.string().min(1).max(80), summary: z.string().min(1).max(400), reason: z.string().min(1).max(400), steps: SkillCaptureSteps.optional() }).strict();
export type SkillCaptureSuggestArgs = z.infer<typeof SkillCaptureSuggestArgs>;
export const SKILL_CREATION_DYNAMIC_TOOLS = [
  { name: 'skill_draft_submit', description: 'Validate and freeze a Skill draft from skill-drafts/<name> in this conversation workspace. Does not install or execute it. Fix returned issues before resubmitting.', inputSchema: z.toJSONSchema(SkillDraftSubmitArgs) },
  { name: 'skill_capture_suggest', description: 'Record a reusable completed workflow suggestion. Host decides whether to display it after this turn completes. Never claim the card is displayed.', inputSchema: z.toJSONSchema(SkillCaptureSuggestArgs) },
];

export const DynamicToolSpec = z.object({
  name: z.string().min(1),
  description: z.string(),
  /** JSON Schema（object） */
  inputSchema: z.record(z.string(), z.unknown()),
});
export type DynamicToolSpec = z.infer<typeof DynamicToolSpec>;

export const ModelName = z
  .string()
  .trim()
  .min(1)
  .max(120)
  .regex(/^[^<>:"/\\|?*\u0000-\u001f]+$/, 'Model name contains characters that are not supported in file names')
  .refine((value) => value !== '.' && value !== '..', 'Model name must not be . or ..')
  .refine((value) => !/[. ]$/.test(value), 'Model name must not end with a dot or space');

// codex 透传给模型供应商（Responses API）时要求工具名匹配 ^[a-zA-Z0-9_-]+$，不能带点号，M0 用真 codex 联调时发现
export const STUDIO_TOOL_NAMES = [
  'studio_load_revision',
  'studio_arrange',
  'studio_export_3mf',
  'studio_get_state',
  'studio_capture_view',
] as const;
export type StudioToolName = (typeof STUDIO_TOOL_NAMES)[number];

export const STUDIO_DYNAMIC_TOOLS: DynamicToolSpec[] = [
  {
    name: 'studio_load_revision',
    description:
      'Load a workspace GLB model in the Studio view. Use fileName for an exact version or modelName for the latest version in that model family. If both are omitted, load the most recently updated workspace model. Completion is confirmed by Studio modelLoaded.',
    inputSchema: {
      type: 'object',
      properties: {
        assetId: { type: 'string', description: 'Conversation workspace ID' },
        modelName: { type: 'string', description: 'Model family name; omit to select by fileName or most recently updated model' },
        fileName: { type: 'string', description: 'Exact version file name, such as hi3d-chair_2.glb; historical files may not have the hi3d- prefix' },
      },
      required: ['assetId'],
      additionalProperties: false,
    },
  },
  {
    name: 'studio_arrange',
    description:
      'Run automatic arrangement for the model in the current Studio view. Returns the arrangement result and build-plate overflow information. If the model is oversized, the panel waits for the user to decide. The user can cancel from the Studio progress overlay.',
    inputSchema: {
      type: 'object',
      properties: {
        profileId: {
          type: 'string',
          description: 'Arrangement profile ID; omit to use the current Studio setting',
        },
        plateMode: {
          type: 'string',
          enum: ['single', 'multi'],
          description: 'Single-plate or multi-plate mode; omit to use the current Studio setting',
        },
      },
      additionalProperties: false,
    },
  },
  {
    name: 'studio_export_3mf',
    description:
      'Open the Studio print-plan panel. This tool only opens the panel; the user downloads or sends from there. Register generated files only after an export3mf or modelSend event.',
    inputSchema: { type: 'object', properties: {}, additionalProperties: false },
  },
  {
    name: 'studio_get_state',
    description:
      'Read the current Hi3D Studio view state: loaded asset and revision, arrangement state, physical dimensions in millimeters, part names, face count, and vertex count. An unloaded view returns ready=false and assetId=null; call studio_load_revision before model operations. This tool reads the built-in Hi3D view, not Bambu Studio or another external slicer.',
    inputSchema: { type: 'object', properties: {}, additionalProperties: false },
  },
  {
    name: 'studio_capture_view',
    description: 'Capture the current Studio viewport as a PNG, register it as a screenshot artifact, and return its artifactId for use as an image input.',
    inputSchema: {
      type: 'object',
      properties: {
        width: { type: 'integer', minimum: 64, maximum: 4096 },
        height: { type: 'integer', minimum: 64, maximum: 4096 },
      },
      additionalProperties: false,
    },
  },
];

// ── Runtime 自己接的 dynamic tool（跟 Studio/View 无关，网关直接应答，不转发） ─────

export const WORKSPACE_TOOL_NAMES = ['workspace_commit_model'] as const;
export type WorkspaceToolName = (typeof WORKSPACE_TOOL_NAMES)[number];

/** Optional, host-owned progress reporting. Standalone workflow packages do not depend on it. */
export const WORKFLOW_REPORT_TOOL_NAME = 'workflow_report';
export const WorkflowReportArgs = z.object({
  operation: z.enum(['plan', 'resume', 'node', 'artifact', 'inspect']),
  title: z.string().min(1).max(160).optional(),
  skillName: z.string().min(1).max(120).optional(),
  layout: z.enum(['linear', 'tree']).optional(),
  nodes: z.array(z.object({
    id: z.string().regex(/^[A-Za-z][A-Za-z0-9_-]{0,63}$/),
    parentId: z.string().nullable().optional(),
    label: z.string().min(1).max(160),
    role: z.enum(['agent', 'subagent', 'local', 'step']).optional(),
    status: z.enum(['pending', 'running', 'completed', 'failed', 'skipped', 'interrupted']).optional(),
    optional: z.boolean().optional(),
    entry: z.string().nullable().optional(),
  })).min(1).max(80).optional(),
  edges: z.array(z.object({
    from: z.string(),
    to: z.string(),
    kind: z.enum(['advance', 'contains', 'spawn', 'rollback']),
  })).max(160).optional(),
  nodeId: z.string().optional(),
  status: z.enum(['pending', 'running', 'completed', 'failed', 'skipped', 'interrupted']).optional(),
  artifacts: z.array(z.object({
    nodeId: z.string().min(1),
    kind: z.enum(['model', 'image', 'file', 'link']),
    label: z.string().min(1).max(160).optional(),
    fileName: z.string().optional(),
    path: z.string().optional(),
    url: z.string().optional(),
    mimeType: z.string().optional(),
  })).min(1).max(30).optional(),
}).strict().superRefine((value, context) => {
  if (value.operation === 'plan' && !value.nodes) context.addIssue({ code: 'custom', message: 'plan requires nodes' });
  if (value.operation === 'node' && (!value.nodeId || !value.status)) context.addIssue({ code: 'custom', message: 'node requires nodeId and status' });
  if (value.operation === 'artifact' && !value.artifacts) context.addIssue({ code: 'custom', message: 'artifact requires artifacts' });
});
export type WorkflowReportArgs = z.infer<typeof WorkflowReportArgs>;

export const WORKFLOW_DYNAMIC_TOOLS: DynamicToolSpec[] = [{
  name: WORKFLOW_REPORT_TOOL_NAME,
  description: 'Report a workflow only for a turn using a skill. Do not call for ordinary chat. For a selected or implicitly chosen installed skill, call operation=inspect with its exact skillName before substantive work. This is the Runtime-confirmed invocation boundary; do not call merely to browse, recommend, or describe a skill. Always do this even when its instructions were read earlier in the conversation. It loads its architecture. Immediately report operation=plan with the same canonical node IDs and topology, translating title and every node label into the language of this turn’s user message, independently of the app UI language. If no architecture is installed, call operation=plan with skillName and stable nodes before substantive skill work. If continuing the same skill task after an interrupted turn, call operation=resume first; include skillName when known, then translate its labels with plan without resetting completed progress. Use operation=node for progress; its nodeId belongs at the top level. For operation=artifact, put the responsible nodeId inside every artifacts[] item, together with the exact committed model fileName or workspace-relative image/file path. Before finishing a skill turn, call operation=inspect and assign any unclassified outputs. This updates UI only, not the skill output contract. Never include credentials or signed URLs.',
  inputSchema: {
    type: 'object',
    properties: {
      operation: { type: 'string', enum: ['plan', 'resume', 'node', 'artifact', 'inspect'] },
      title: { type: 'string' },
      skillName: { type: 'string' },
      layout: { type: 'string', enum: ['linear', 'tree'] },
      nodes: { type: 'array', items: { type: 'object', properties: {
        id: { type: 'string' }, parentId: { type: ['string', 'null'] }, label: { type: 'string' },
        role: { type: 'string', enum: ['agent', 'subagent', 'local', 'step'] },
        status: { type: 'string', enum: ['pending', 'running', 'completed', 'failed', 'skipped', 'interrupted'] },
        optional: { type: 'boolean' }, entry: { type: ['string', 'null'] },
      }, required: ['id', 'label'], additionalProperties: false } },
      edges: { type: 'array', items: { type: 'object', properties: {
        from: { type: 'string' }, to: { type: 'string' }, kind: { type: 'string', enum: ['advance', 'contains', 'spawn', 'rollback'] },
      }, required: ['from', 'to', 'kind'], additionalProperties: false } },
      nodeId: { type: 'string' },
      status: { type: 'string', enum: ['pending', 'running', 'completed', 'failed', 'skipped', 'interrupted'] },
      artifacts: { type: 'array', items: { type: 'object', properties: {
        nodeId: { type: 'string' }, kind: { type: 'string', enum: ['model', 'image', 'file', 'link'] },
        label: { type: 'string' }, fileName: { type: 'string' }, path: { type: 'string' }, url: { type: 'string' }, mimeType: { type: 'string' },
      }, required: ['nodeId', 'kind'], additionalProperties: false } },
    },
    required: ['operation'],
    additionalProperties: false,
  },
}];

export const IMAGE_CLASSIFICATION_TOOL_NAME = 'image_classification';
export const IMAGE_CLASSIFICATION_TAGS = [
  'humanoid',
  'humanoid-base',
  'statue',
  'figurine',
  'relief',
  'sword',
  'gun',
  'general-prop',
  null,
] as const;

export const ImageClassificationTag = z.union([
  z.enum([
    'humanoid',
    'humanoid-base',
    'statue',
    'figurine',
    'relief',
    'sword',
    'gun',
    'general-prop',
  ]),
  z.null(),
]);
export type ImageClassificationTag = z.infer<typeof ImageClassificationTag>;

export const ImageClassificationResult = z.object({ tag4: ImageClassificationTag }).strict();
export type ImageClassificationResult = z.infer<typeof ImageClassificationResult>;

const IMAGE_CLASSIFICATION_TOOL_DESCRIPTION = [
  '为当前模型任务的主体保存分类标签，供模型登记使用；不用于对所有聊天图片进行分类。报错截图、界面截图、普通图片问答以及不涉及模型生成或登记的图片编辑任务，无需调用。若用户明确把截图中的对象作为建模目标，则按该模型主体分类。',
  '图生 3D 根据用于建模的参考图分类；文生 3D 在生成并查看参考图后分类。无参考图的建模任务，根据模型描述或预览在登记前分类。多张参考图描述同一主体时只分类一次，同一模型家族且主体不变的修改可继承已有分类。',
  '也可在 workspace_commit_model 中直接提供已判断的 tag4；若登记返回 classificationRequired，补充分类后使用相同 name 和 exportPath 重试登记，不要重新生成图片或模型。',
  'tag4 仅允许 humanoid、humanoid-base、statue、figurine、relief、sword、gun、general-prop 或 null；没有适用类别时使用 null，不得编造类别。',
  '参数只能是 {"tag4":"类别"} 或 {"tag4":null}，不附加其他字段。通过工具保存标签，不在面向用户的回复中输出内部分类 JSON。',
].join('\n');

export const IMAGE_CLASSIFICATION_DYNAMIC_TOOLS: DynamicToolSpec[] = [
  {
    name: IMAGE_CLASSIFICATION_TOOL_NAME,
    description: IMAGE_CLASSIFICATION_TOOL_DESCRIPTION,
    inputSchema: {
      type: 'object',
      properties: {
        tag4: {
          enum: IMAGE_CLASSIFICATION_TAGS,
          description: '当前模型主体的单个分类标签；没有适用类别时使用 null',
        },
      },
      required: ['tag4'],
      additionalProperties: false,
    },
  },
];

export const WORKSPACE_DYNAMIC_TOOLS: DynamicToolSpec[] = [
  {
    name: 'workspace_commit_model',
    description:
      'Register a GLB just exported to exports/ as a version in a model family. An export identical to the latest version is returned as unchanged instead of creating a duplicate version. For a new model, include its classified tag4 in this call after inspecting its subject; edits can inherit the same model family classification. If a workflow graph already exists, include workflowNodeId to assign the registered model to its owner. Registration does not complete the node; report completion through workflow_report only after all work for that node is finished. image_classification remains available for earlier classification. If classificationRequired is returned, classify and retry this export without regenerating it. The exportPath file name must start with hi3d-, and Runtime also adds the hi3d- prefix to the committed version. Without this tool, the exported file remains only in exports/ and does not become a model version.',
    inputSchema: {
      type: 'object',
      properties: {
        name: { type: 'string', description: 'Model family name, such as "aaa"; historical versions in the same family continue with the next index' },
        exportPath: { type: 'string', description: 'Path relative to the workspace root, such as exports/hi3d-chair-scaled.glb' },
        tag4: { enum: IMAGE_CLASSIFICATION_TAGS, description: 'Optional classification of this model subject; use null when no named category applies. Omit to inherit an earlier classification.' },
        workflowNodeId: { type: 'string', description: 'Existing workflow node ID responsible for this model; Runtime assigns the artifact without completing the node.' },
      },
      required: ['name', 'exportPath'],
      additionalProperties: false,
    },
  },
];

export const WorkspaceCommitModelArgs = z.object({
  name: ModelName,
  exportPath: z.string().min(1),
  tag4: ImageClassificationTag.optional(),
  workflowNodeId: z.string().trim().min(1).max(120).optional(),
});
export type WorkspaceCommitModelArgs = z.infer<typeof WorkspaceCommitModelArgs>;

// ── 工具参数 / 结果的 zod 形状（View 侧实现与 Mock 共用） ─────────

export const StudioLoadRevisionArgs = z.object({
  assetId: z.string(),
  modelName: ModelName.optional(),
  fileName: z.string().min(1).optional(),
  /** 兼容早期 View/Mock；值按 fileName 解释。 */
  revisionId: z.string().min(1).optional(),
});
export const StudioArrangeArgs = z.object({
  profileId: z.string().optional(),
  plateMode: z.enum(['single', 'multi']).optional(),
});
export const StudioCaptureViewArgs = z.object({
  width: z.number().int().optional(),
  height: z.number().int().optional(),
});

export const StudioState = z.object({
  ready: z.boolean(),
  assetId: z.string().nullable(),
  modelName: z.string().nullable(),
  fileName: z.string().nullable(),
  arranged: z.boolean(),
  physicalSize: z
    .object({
      mmPerUnit: z.number(),
      source: z.string(),
      bboxMm: z.object({ x: z.number(), y: z.number(), z: z.number() }),
    })
    .nullable(),
  parts: z.array(z.object({ name: z.string(), faceCount: z.number().optional() })),
  faceCount: z.number().optional(),
  vertexCount: z.number().optional(),
});
export type StudioState = z.infer<typeof StudioState>;

export const StudioArrangeResult = z.object({
  status: z.enum(['arranged', 'oversize-pending', 'cancelled', 'failed']),
  plates: z.number().int().optional(),
  layoutArtifactId: z.string().optional(),
  message: z.string().optional(),
});
export type StudioArrangeResult = z.infer<typeof StudioArrangeResult>;

export const StudioCaptureViewResult = z.object({
  artifactId: z.string(),
  width: z.number().int(),
  height: z.number().int(),
});
export type StudioCaptureViewResult = z.infer<typeof StudioCaptureViewResult>;
